create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,title text not null,body text not null,type text not null default 'general',is_read boolean not null default false,created_at timestamptz not null default now());alter table if exists public.products add column if not exists is_featured boolean not null default false;alter table if exists public.payment_methods add column if not exists sort_order integer not null default 0;alter table public.notifications enable row level security;drop policy if exists notifications_read on public.notifications;create policy notifications_read on public.notifications for select using(user_id=auth.uid() or user_id is null or public.is_admin());drop policy if exists notifications_update on public.notifications;create policy notifications_update on public.notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());